bool isAnagram(const string& s, const string& t) {
    if (s.size() != t.size()) return false;   // cheap early reject
    int count[26] = {0};
    for (size_t i = 0; i < s.size(); ++i) {
        ++count[s[i] - 'a'];
        --count[t[i] - 'a'];
    }
    for (int c : count) if (c != 0) return false;
    return true;
}

