vector<int> intersection(vector<int>& a, vector<int>& b) {
    if (a.size() > b.size()) swap(a, b);      // hash the smaller side
    unordered_set<int> small(a.begin(), a.end());
    vector<int> out;
    for (int x : b)
        if (small.erase(x))                   // erase returns 1 on first hit only
            out.push_back(x);                 // ...which also enforces uniqueness
    return out;
}

