def intersection(a: list[int], b: list[int]) -> list[int]:
    if len(a) > len(b):            # hash the smaller side
        a, b = b, a
    small = set(a)
    out = []
    for x in b:
        if x in small:
            small.remove(x)        # removing on first hit enforces uniqueness
            out.append(x)
    return out

