int missingNumberSum(const vector<int>& nums) {
    long long n = nums.size();
    long long expected = n * (n + 1) / 2;     // long long: n^2 overflows int
    long long actual = 0;
    for (int x : nums) actual += x;
    return (int)(expected - actual);
}

int missingNumberXor(const vector<int>& nums) {
    int result = (int)nums.size();            // start with n, the index never visited
    for (int i = 0; i < (int)nums.size(); ++i)
        result ^= i ^ nums[i];                // every present value cancels its index
    return result;
}

