int kthSmallest(const vector<int>& a, int k) {
    priority_queue<int> pq;                 // MAX-heap of the k smallest so far
    for (int x : a) {
        pq.push(x);
        if ((int)pq.size() > k) pq.pop();   // drop the largest; k smallest survive
    }
    return pq.top();                        // the largest of the k smallest
}

