import heapq


def kth_smallest(a: list[int], k: int) -> int:
    pq = []                          # MAX-heap (negated) of the k smallest so far
    for x in a:
        heapq.heappush(pq, -x)
        if len(pq) > k:
            heapq.heappop(pq)        # drop the largest; k smallest survive
    return -pq[0]                    # the largest of the k smallest

