vector<int> nextGreaterElement(const vector<int>& nums1, const vector<int>& nums2) {
    unordered_map<int,int> nextGreater;    // value -> its next greater in nums2
    stack<int> st;                         // decreasing from bottom to top
    for (int i = (int)nums2.size() - 1; i >= 0; --i) {
        while (!st.empty() && st.top() <= nums2[i]) st.pop();   // too small to matter
        nextGreater[nums2[i]] = st.empty() ? -1 : st.top();
        st.push(nums2[i]);
    }
    vector<int> out;
    out.reserve(nums1.size());
    for (int x : nums1) out.push_back(nextGreater[x]);
    return out;
}

