def next_greater_element(nums1: list[int], nums2: list[int]) -> list[int]:
    next_greater = {}                # value -> its next greater in nums2
    st = []                          # decreasing from bottom to top
    for x in reversed(nums2):
        while st and st[-1] <= x:
            st.pop()                 # too small to ever be an answer
        next_greater[x] = st[-1] if st else -1
        st.append(x)
    return [next_greater[x] for x in nums1]

