// a must be sorted. Counts values in the inclusive range [lo, hi].
int countInRange(const vector<int>& a, int lo, int hi) {
    auto left  = lower_bound(a.begin(), a.end(), lo);   // first >= lo
    auto right = upper_bound(a.begin(), a.end(), hi);   // first > hi
    return (int)max<ptrdiff_t>(0, right - left);        // inverted range => 0, never negative
}
